SCALE = 50
BASE_PLANET_SIZE = 35
BASE_ISOLATED_SIZE = 8

# === ФУНКЦИЯ РАСЧЁТА РАЗМЕРА ПО НАСЕЛЕНИЮ ===

def get_planet_size(pop):
    if pop <= 0.1:
        return BASE_PLANET_SIZE * 0.6
    elif pop <= 0.4:
        return BASE_PLANET_SIZE * 0.8
    elif pop <= 1.0:
        return BASE_PLANET_SIZE
    elif pop <= 3.0:
        return BASE_PLANET_SIZE * 1.1
    elif pop <= 10.0:
        return BASE_PLANET_SIZE * 1.2
    else:
        return BASE_PLANET_SIZE * 1.3

# === ФУНКЦИЯ РАСЧЁТА РАЗМЕРА ИЗОЛИРОВАННЫХ СИСТЕМ ===

def get_isolated_size(size_val):
    if size_val == 1:
        return BASE_ISOLATED_SIZE * 0.4
    elif size_val == 2:
        return BASE_ISOLATED_SIZE
    else:
        return BASE_ISOLATED_SIZE * 1.6

