# === JS-АНИМАЦИЯ ПУЛЬСАЦИИ УЗЛОВ И РЁБЕР ===

NODE_SPEED = 0.4
EDGE_SPEED = 0.2
NODE_MIN_ALPHA = 0.8
EDGE_MIN_ALPHA = 0.5
PULSE_BORDER_MIN = 2
PULSE_BORDER_MAX = 5
PULSE_BORDER_COLOR = "rgba(255, 0, 0, 0.9)"
PULSE_BORDER_DASHES = [4, 3]
siege_helpers_js = f"""
<script>
window.SIEGE_END_DAY = {SIEGE_END_DAY};
window.isPostSiege = function() {{
    var d = parseInt(localStorage.getItem('galaxy_current_day') || '1', 10);
    return d >= window.SIEGE_END_DAY;
}};
</script>
"""
pulse_js = f"""
<script>
window.addEventListener('load', function() {{
    setTimeout(function() {{
        window.nodeDS = null;
        window.edgeDS = null;

        try {{ if (typeof nodes !== 'undefined') nodeDS = nodes; }} catch(e) {{}}
        if (!nodeDS) {{
            try {{
                var net = network;
                if (net && net.body && net.body.data && net.body.data.nodes) {{
                    nodeDS = net.body.data.nodes;
                }}
            }} catch(e) {{}}
        }}
        if (!nodeDS) {{
            var c = document.getElementById('mynetwork');
            if (c && c.network && c.network.body && c.network.body.data && c.network.body.data.nodes) {{
                nodeDS = c.network.body.data.nodes;
            }}
        }}

        try {{ if (typeof edges !== 'undefined') edgeDS = edges; }} catch(e) {{}}
        if (!edgeDS) {{
            try {{
                var net2 = network;
                if (net2 && net2.body && net2.body.data && net2.body.data.edges) {{
                    edgeDS = net2.body.data.edges;
                }}
            }} catch(e) {{}}
        }}
        if (!edgeDS) {{
            var c2 = document.getElementById('mynetwork');
            if (c2 && c2.network && c2.network.body && c2.network.body.data && c2.network.body.data.edges) {{
                edgeDS = c2.network.body.data.edges;
            }}
        }}

        if (!nodeDS) {{ console.error('Cannot find nodes DataSet!'); return; }}
        if (!edgeDS) {{ console.error('Cannot find edges DataSet!'); return; }}

        var targetNodeIds = {json.dumps(pulse_nodes)};
        if (window.isPostSiege && window.isPostSiege()) {{
        var idx = targetNodeIds.indexOf('Треа');
        if (idx !== -1) targetNodeIds.splice(idx, 1);
        }}
        var baseNodeColors = {{}};
        targetNodeIds.forEach(function(id) {{
            var node = nodeDS.get(id);
            if (node) {{
                var c = node.color;
                if (typeof c === 'string') {{
                    baseNodeColors[id] = c;
                }} else if (c && typeof c === 'object') {{
                    baseNodeColors[id] = c.background || c.color || '#FFFFFF';
                }} else {{
                    baseNodeColors[id] = '#FFFFFF';
                }}
            }}
        }});

        var targetEdgeIds = {json.dumps(high_traffic_edge_ids)};
        var baseEdgeColors = {{}};
        targetEdgeIds.forEach(function(id) {{
            var edge = edgeDS.get(id);
            if (edge) {{
                var c = edge.color;
                if (typeof c === 'string') {{
                    baseEdgeColors[id] = c;
                }} else if (c && typeof c === 'object') {{
                    baseEdgeColors[id] = c.color || '#FFFFFF';
                }} else {{
                    baseEdgeColors[id] = '#FFFFFF';
                }}
            }}
        }});

        function hexToRgb(hex) {{
            var result = /^#?([a-f\\d]{{2}})([a-f\\d]{{2}})([a-f\\d]{{2}})$/i.exec(hex);
            return result ? [
                parseInt(result[1], 16),
                parseInt(result[2], 16),
                parseInt(result[3], 16)
            ] : [255, 255, 255];
        }}

        var phaseNodes = 0;
        var phaseEdges = 0;

        var nodeSpeed = {NODE_SPEED};
        var edgeSpeed = {EDGE_SPEED};
        var nodeMinAlpha = {NODE_MIN_ALPHA};
        var edgeMinAlpha = {EDGE_MIN_ALPHA};
        var nodeAmp = 1.0 - nodeMinAlpha;
        var edgeAmp = 1.0 - edgeMinAlpha;
                // Базовые размеры пульсирующих узлов — чтобы vis-network перерисовывал их
        var baseNodeSizes = {{}};
        targetNodeIds.forEach(function(id) {{
            var n = nodeDS.get(id);
            if (n && n.size) baseNodeSizes[id] = n.size;
        }});
        var PULSE_BORDER_MIN = {PULSE_BORDER_MIN};
        var PULSE_BORDER_MAX = {PULSE_BORDER_MAX};
        var PULSE_BORDER_COLOR = "{PULSE_BORDER_COLOR}";
        var PULSE_BORDER_DASHES = {json.dumps(PULSE_BORDER_DASHES)};

// === БЕГУЩИЕ ОГОНЬКИ ===
var runners = {json.dumps(main_edge_runners)};
var runnerPhase = 0;

setInterval(function() {{
    runnerPhase = (runnerPhase + 0.025) % 1;    // 
    var runnerUpdates = runners.map(function(r) {{
        var t = (runnerPhase + (r.phase_offset || 0)) % 1;
        if (r.reverse) t = 1 - t;
        var x = r.x1 + (r.x2 - r.x1) * t;
        var y = r.y1 + (r.y2 - r.y1) * t;
        return {{ id: r.id, x: x, y: y }};
    }});
    if (runnerUpdates.length > 0) nodeDS.update(runnerUpdates);
}}, 50);

setInterval(function() {{
    phaseNodes += nodeSpeed;
    phaseEdges += edgeSpeed;

    var alphaNode = nodeMinAlpha + nodeAmp * (0.5 + 0.5 * Math.sin(phaseNodes));
    var alphaEdge = edgeMinAlpha + edgeAmp * (0.5 + 0.5 * Math.sin(phaseEdges));
    var borderNode = PULSE_BORDER_MIN + (PULSE_BORDER_MAX - PULSE_BORDER_MIN) *
                                        (0.5 + 0.5 * Math.sin(phaseNodes));

            var nodeUpdates = [];
            targetNodeIds.forEach(function(id) {{
                var base = baseNodeColors[id];
                if (!base) return;
                var rgb = hexToRgb(base);
                var _baseSize = baseNodeSizes[id] || 20;
                nodeUpdates.push({{
                    id: id,
                    size: _baseSize + 0.01,
                    color: {{
                        background: 'rgba(' + rgb[0] + ',' + rgb[1] + ',' + rgb[2] + ',' + alphaNode.toFixed(3) + ')',
                        border: PULSE_BORDER_COLOR
                    }},
                    borderWidth: borderNode,
                    shapeProperties: {{
                        borderDashes: PULSE_BORDER_DASHES
                    }}
                }});
            }});

    var edgeUpdates = [];
    targetEdgeIds.forEach(function(id) {{
        var base = baseEdgeColors[id];
        if (!base) return;
        var rgb = hexToRgb(base);
        edgeUpdates.push({{
            id: id,
            color: 'rgba(' + rgb[0] + ',' + rgb[1] + ',' + rgb[2] + ',' + alphaEdge.toFixed(3) + ')'
        }});
    }});

    if (nodeUpdates.length > 0) nodeDS.update(nodeUpdates);
    if (edgeUpdates.length > 0) edgeDS.update(edgeUpdates);
}}, 50);
    }}, 1500);
}});
</script>
"""
toggle_code = """
        window.colorsMain = %s;
        window.colorsAlt = %s;
        window.currentMode = 'main';

        // === СВОРАЧИВАНИЕ ЛЕГЕНДЫ ===
        window.legendCollapsed = false;
        window.toggleLegendCollapse = function() {
            window.legendCollapsed = !window.legendCollapsed;
            ['legend1', 'legend2'].forEach(function(id) {
                var box = document.getElementById(id);
                if (!box) return;
                var body = box.querySelector('.legend-body');
                var icon = box.querySelector('.legend-collapse-icon');
                if (body) body.classList.toggle('collapsed', window.legendCollapsed);
                if (icon) icon.textContent = window.legendCollapsed ? '▶' : '▼';
            });
        };

        function toggleMode() {
            window.currentMode = window.currentMode === 'main' ? 'alt' : 'main';
            var colors = window.currentMode === 'main' ? window.colorsMain : window.colorsAlt;
            var updates = [];
            Object.keys(colors).forEach(function(name) {
                updates.push({ id: name, color: colors[name] });
                if (baseNodeColors[name]) {
                    baseNodeColors[name] = colors[name];
                }
            });
            nodeDS.update(updates);
            var l1 = document.getElementById('legend1wrap');
            var l2 = document.getElementById('legend2wrap');
            if (l1) l1.style.display = window.currentMode === 'main' ? 'block' : 'none';
            if (l2) l2.style.display = window.currentMode === 'alt' ? 'block' : 'none';
        }

        var btn = document.getElementById('legendToggle');
        if (btn) btn.addEventListener('click', toggleMode);
        document.addEventListener('keydown', function(e) {
            if (e.key === 'l' || e.key === 'L' || e.key === '\\u0434' || e.key === '\\u0414') {
                toggleMode();
            }
        });
""" % (json.dumps(planet_colors), json.dumps(planet_colors_alt))

pulse_js = pulse_js.replace("    }, 1500);", toggle_code + "\n    }, 1500);")
edge_speed_data = []
