role_js = """
<script>
(function() {
    var ROLE_KEY = 'galaxy_player_role';

    // === РОЛИ И ПАРОЛИ ===
    // Пароли можно менять как хочешь — просто поменяй цифры здесь.
    var ROLES = {
    
        '105': {
            id: 'imperial',
            emoji: '🏛',
            name: 'Имперец',
            welcome: 'Имперское командование подтверждает вашу аккредитацию. Добро пожаловать на службу, {name}.'
        },
        '501': {
            id: 'gamemaster',
            emoji: '🎲',
            name: 'Мастер',
            welcome: 'Добро пожаловать, мастер. Все данные галактики открыты для вас, {name}.'
        },
        '218': {
            id: 'rebel',
            emoji: '🔥',
            name: 'Мятежник',
            welcome: 'Свободная частота: связь установлена, {name}. Будьте осторожны — Империя повсюду.'
        },
        '417': {
            id: 'resistance_officer',
            emoji: '⚔',
            name: 'Офицер сопротивления',
            welcome: 'Офицер, ваша высадка прошла успешно. Ожидайте дальнейших указаний, {name}.'
        },
        '777': {
            id: 'jedi',
            emoji: '✦',
            name: 'Джедай',
            welcome: 'Через Силу ощущается дисбаланс. Галактика ждёт тебя, {name}.'
        },
        '666': {
            id: 'pirate',
            emoji: '🏴☠️',
            name: 'Пират',
            welcome: 'Бар «Ржавый шлюз» приветствует, {name}. Для тебя всегда найдётся работёнка.'
        },
        '000': {
            id: 'civilian',
            emoji: '🏠',
            name: 'Мирный житель',
            welcome: 'Вы прибыли на {world}. Осторожнее на улицах, {name}.'
        }
    };

    function loadRole() {
        try {
            var raw = localStorage.getItem(ROLE_KEY);
            if (!raw) return null;
            var r = JSON.parse(raw);
            if (r && r.id) return r;
        } catch (e) {}
        return null;
    }

    function saveRole(role) {
        try { localStorage.setItem(ROLE_KEY, JSON.stringify(role)); } catch(e) {}
    }

    function resetRole() {
        try { localStorage.removeItem(ROLE_KEY); } catch(e) {}
    }

    function getPlayerWorld() {
        try {
            var w = localStorage.getItem('galaxy_player_location');
            if (w) return w;
        } catch(e) {}
        return 'Аэродия';
    }

    function getCurrentDay() {
        var d = parseInt(localStorage.getItem('galaxy_current_day') || '1', 10);
        return isNaN(d) ? 1 : d;
    }

    function showWelcomePopup(role, name) {
        var popup = document.getElementById('welcomePopup');
        var emojiEl = document.getElementById('welcomeEmoji');
        var titleEl = document.getElementById('welcomeTitle');
        var textEl = document.getElementById('welcomeText');

        if (!popup) return;

        emojiEl.textContent = role.emoji || '🎭';
        titleEl.textContent = role.name || 'Добро пожаловать';

        var text = (role.welcome || '')
            .replace(/\\{name\\}/g, name || 'странник')
            .replace(/\\{world\\}/g, getPlayerWorld());

        textEl.textContent = text;
        popup.classList.add('visible');
    }

    function renderBadge(role) {
        var el = document.getElementById('roleBadge');
        if (!el) return;
        if (!role || !role.id) {
            el.style.display = 'none';
            return;
        }
        el.textContent = role.emoji + ' ' + role.name + ' · ' + role.name_player;
        el.style.display = 'block';
    }

    function showOverlay() {
        var ov = document.getElementById('roleOverlay');
        var nameInput = document.getElementById('roleNameInput');
        var passInput = document.getElementById('rolePassInput');
        var err = document.getElementById('roleError');

        err.textContent = '';
        nameInput.value = '';
        passInput.value = '';
        ov.classList.add('visible');
        setTimeout(function() { nameInput.focus(); }, 100);
    }

    function hideOverlay() {
        document.getElementById('roleOverlay').classList.remove('visible');
    }

    function tryLogin() {
        var name = document.getElementById('roleNameInput').value.trim();
        var pass = document.getElementById('rolePassInput').value.trim();
        var err = document.getElementById('roleError');

        if (!name) {
            err.textContent = 'Введите имя.';
            return;
        }
        if (!pass) {
            err.textContent = 'Введите пароль.';
            return;
        }
        var role = ROLES[pass];
        if (!role) {
            err.textContent = 'Неверный пароль.';
            return;
        }

        var stored = {
            id: role.id,
            emoji: role.emoji,
            name: role.name,
            name_player: name,
            welcome: role.welcome,
            chosen: Date.now()
        };
        saveRole(stored);
        hideOverlay();
        renderBadge(stored);
        showWelcomePopup(stored, name);
    }

    function skipLogin() {
        var stored = {
            id: null,
            emoji: '',
            name: 'Без роли',
            name_player: '',
            chosen: Date.now()
        };
        saveRole(stored);
        hideOverlay();
        renderBadge(null);
    }

    function init() {
        var existing = loadRole();
        if (existing) {
            renderBadge(existing && existing.id ? existing : null);
            return;
        }
        showOverlay();

        document.getElementById('roleConfirm').addEventListener('click', tryLogin);
        document.getElementById('roleSkip').addEventListener('click', skipLogin);
                var wc = document.getElementById('welcomeClose');
        if (wc) {
            wc.addEventListener('click', function() {
                document.getElementById('welcomePopup').classList.remove('visible');
            });
        }

        // Enter в любом поле — попытка входа
        ['roleNameInput', 'rolePassInput'].forEach(function(id) {
            document.getElementById(id).addEventListener('keydown', function(e) {
                if (e.key === 'Enter') { e.preventDefault(); tryLogin(); }
            });
        });

        // Esc — пропустить
        document.addEventListener('keydown', function(e) {
            var ov = document.getElementById('roleOverlay');
            if (ov && ov.classList.contains('visible') && e.key === 'Escape') {
                skipLogin();
            }
        });
    }

    window.resetPlayerRole = resetRole;
    window.getPlayerRole = loadRole;

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        setTimeout(init, 2000);
    }
})();
</script>
"""
