# === ПРОЦЕДУРНЫЙ ГЕНЕРАТОР ОСАДЫ АНТИГА ПРАЙМ ===
import random

def generate_antiga_script():
    """Детерминированно генерирует осаду Антиги Прайм на 40 дней.

    Фронт продвигается последовательно: армия сидит на одном рубеже
    несколько дней, потом рубеж «падает» и начинается следующий.
    """
    rng = random.Random(20241006)
    script = []
    start_day = SIEGES["Антига Прайм"]["start_day"]
    rubezhi = SIEGES["Антига Прайм"]["rubezhi"]
    DAYS = 40

    FRONT_DURATION = 4
    current_front_idx = 1

    news_templates = {
        "battle": [
            ("Имперский Вестник", "Тарсонис продолжает наступление",
             "Силы Тарсониса вновь атаковали позиции коалиции на рубеже «{front}». Обе стороны несут потери."),
            ("«Голос окраин»", "Бои на «{front}» не прекращаются",
             "Тарсонис бросил в бой новые подразделения. Коалиция держит оборону."),
        ],
        "lull": [
            ("«Окраинный Вестник»", "Затишье на «{front}»",
             "Обе стороны перегруппировывают силы после тяжёлых боёв."),
        ],
        "reinforcement_tars": [
            ("Имперский Вестник", "Тарсонис получил подкрепление",
             "С орбиты высадились свежие части. Атака продолжится в ближайшие дни."),
        ],
        "reinforcement_coal": [
            ("«Свободная частота»", "Коалиция получила помощь",
             "На «{front}» прибыли добровольцы из соседних систем."),
        ],
        "raid": [
            ("«Чёрный канал»", "Рейд на «{front}»",
             "Диверсионная группа коалиции атаковала тылы Тарсониса. Уничтожены склады и техника."),
        ],
        "maneuver": [
            ("«Голос нейтральных миров»", "Перегруппировка на «{front}»",
             "Силы Тарсониса меняют направление удара. Коалиция готовит ответ."),
        ],
    }

    for day in range(1, DAYS + 1):
        entry = {"day": day}

        if day < start_day:
            entry["log"] = "⏳ Переброска войск Тарсониса к границам системы"
            script.append(entry)
            continue

        front = rubezhi[current_front_idx]
        r = rng.random()

        if r < 0.35:
            e_losses = {
                "soldiers": rng.randint(1500, 4500),
                "militia": rng.randint(0, 800),
                "light": rng.randint(5, 30),
                "heavy": rng.randint(1, 8),
                "civilians_lost": rng.randint(500, 3000),
            }
            c_losses = {
                "soldiers": rng.randint(2000, 6000),
                "light": rng.randint(10, 50),
                "heavy": rng.randint(2, 12),
                "landing": rng.randint(0, 2),
            }
            entry["losses_empire"] = e_losses
            entry["losses_consortium"] = c_losses
            entry["log"] = f"⚔ Тяжёлые бои на рубеже «{front}»"

            agency, head, body = rng.choice(news_templates["battle"])
            entry["news_pool"] = {
                "agency": agency,
                "headline": head.format(front=front),
                "body": body.format(front=front),
                "importance": "important",
            }

        elif r < 0.55:
            entry["log"] = f"⏳ Затишье у «{front}»"
            agency, head, body = rng.choice(news_templates["lull"])
            entry["news_pool"] = {
                "agency": agency,
                "headline": head.format(front=front),
                "body": body.format(front=front),
                "importance": "normal",
            }

        elif r < 0.70:
            if rng.random() < 0.5:
                entry["gain_consortium"] = {
                    "soldiers": rng.randint(20000, 60000),
                    "light": rng.randint(50, 200),
                }
                entry["log"] = f"🚀 Подкрепление Тарсониса высадилось у «{front}»"
                agency, head, body = rng.choice(news_templates["reinforcement_tars"])
            else:
                entry["gain_empire"] = {
                    "soldiers": rng.randint(5000, 25000),
                    "militia": rng.randint(2000, 8000),
                }
                entry["log"] = f"🛡 Коалиция получила добровольцев у «{front}»"
                agency, head, body = rng.choice(news_templates["reinforcement_coal"])
            entry["news_pool"] = {
                "agency": agency,
                "headline": head.format(front=front),
                "body": body.format(front=front),
                "importance": "important",
            }

        elif r < 0.85:
            entry["losses_consortium"] = {
                "soldiers": rng.randint(300, 1500),
                "light": rng.randint(3, 15),
            }
            entry["log"] = f"💥 Рейд коалиции на «{front}»"
            agency, head, body = rng.choice(news_templates["raid"])
            entry["news_pool"] = {
                "agency": agency,
                "headline": head.format(front=front),
                "body": body.format(front=front),
                "importance": "important",
            }

        else:
            entry["log"] = f"⚒ Перегруппировка у «{front}»"
            agency, head, body = rng.choice(news_templates["maneuver"])
            entry["news_pool"] = {
                "agency": agency,
                "headline": head.format(front=front),
                "body": body.format(front=front),
                "importance": "normal",
            }

        # === ПРОДВИЖЕНИЕ ФРОНТА ===
        days_on_this_front = (day - start_day) % FRONT_DURATION
        is_last_front = current_front_idx >= len(rubezhi) - 1
        is_last_day = day >= DAYS - 1

        if (days_on_this_front == FRONT_DURATION - 1
                and not is_last_front
                and not is_last_day):
            entry["capture"] = front
            entry["balance"] = max(15, 50 - current_front_idx * 4)
            entry["log"] += f". Рубеж «{front}» потерян"
            current_front_idx += 1

        script.append(entry)

    return script


SIEGES["Антига Прайм"]["script"] = generate_antiga_script()
