# === СОХРАНЕНИЕ ===
import math

# Явные привязки для случаев, где геометрия даёт не тот якорь
ANCHOR_OVERRIDES = {
    "35": "Треа",       # ближайший по координатам — Шанлоа, но нам нужен Треа
    "8":  "Дракенвелл", # совпадает с геометрией, но оставляем явно
}

ANCHOR_EXTRA_DEFAULT = 5  # «слепой» отрезок в парсеках

_anchor_candidates = [p for p in main_planets if p in pos]

def _pick_anchor(iso_name):
    if iso_name in ANCHOR_OVERRIDES:
        return ANCHOR_OVERRIDES[iso_name]
    if iso_name not in pos:
        return None
    ix, iy = pos[iso_name]
    best, best_d = None, float('inf')
    for cand in _anchor_candidates:
        ax, ay = pos[cand]
        d = math.hypot(ax - ix, ay - iy)
        if d < best_d:
            best_d, best = d, cand
    return best

ISOLATED_ANCHORS = {}
for iso in isolated:
    anchor = _pick_anchor(iso)
    if anchor:
        ISOLATED_ANCHORS[iso] = {"anchor": anchor, "extra": ANCHOR_EXTRA_DEFAULT}
# === РУЧНЫЕ АНКЕРЫ ДЛЯ СПЕЦТОЧЕК ===
# Альфа-1 — узел карточки Альфа-105, в ALL_NODES его нет.
# Привязываем к Викарии (станция вращается на её внешней орбите).
ISOLATED_ANCHORS["Альфа-105"] = {"anchor": "Викария", "extra": 3}
