        html += '<li>90 × Z-95 Headhunter</li>';
        html += '<li>60 × ARC-170</li>';
        html += '<li>60 × V-19 Torrent</li>';
        html += '<li>60 × Alpha-3 Nimbus (V-wing)</li>';
        html += '<li>60 × Y-wing (BTL-B)</li>';
        html += '<li>40 × TIE Defender</li>';
