rayt_quest_js = """
<script>
(function() {
    var QUEST_KEY = 'galaxy_quest_rayt';
    var SUSPICION_THRESHOLD = 5;

    function loadQuest() {
        try {
            var raw = localStorage.getItem(QUEST_KEY);
            return raw ? JSON.parse(raw) : null;
        } catch(e) { return null; }
    }
    function saveQuest(q) {
        try { localStorage.setItem(QUEST_KEY, JSON.stringify(q)); } catch(e) {}
    }
    function getCurrentDay() {
        var d = parseInt(localStorage.getItem('galaxy_current_day') || '1', 10);
        return isNaN(d) ? 1 : d;
    }
    function defaultQuest() {
        return { stage: 1, suspicion: 0, revealed: false, completed: false, failed: false };
    }
    function isDetective(a) { return a && a.skill === 'detective'; }

    function openRaytQuest() {
        var ov = document.getElementById('raytQuestOverlay');
        if (!ov) return;
        ov.classList.add('visible');
        renderQuest();
    }
    function closeRaytQuest() {
        var ov = document.getElementById('raytQuestOverlay');
        if (ov) ov.classList.remove('visible');
    }

    function renderQuest() {
        var body = document.getElementById('raytQuestBody');
        if (!body) return;
        var DATA = window.RAYT_QUEST_DATA;
        var q = loadQuest() || defaultQuest();
        var html = '';

        html += '<div class="rq-progress">';
        DATA.stages.forEach(function(s) {
            var cls = 'rq-step';
            if (q.completed) cls += ' done';
            else if (q.failed) cls += '';
            else if (q.stage > s.num) cls += ' done';
            else if (q.stage === s.num) cls += ' active';
            html += '<div class="' + cls + '"><span class="rq-step-num">ЭТАП ' + s.num +
                    '</span>' + s.name + '</div>';
        });
        html += '</div>';

        if (q.completed || q.revealed) {
            html += '<div class="rq-finale">' + DATA.finale.title + '</div>';
            html += '<div class="rq-finale-text">' + DATA.finale.text + '</div>';
            html += '<div class="rq-actions"><button class="rq-btn rq-btn-close" id="rqCloseBtn">Закрыть</button></div>';
            body.innerHTML = html;
            bindClose();
            return;
        }
        if (q.failed) {
            html += '<div class="rq-failed">' + DATA.failed.title + '</div>';
            html += '<div class="rq-failed-text">' + DATA.failed.text + '</div>';
            html += '<div class="rq-actions"><button class="rq-btn rq-btn-close" id="rqCloseBtn">Закрыть</button></div>';
            body.innerHTML = html;
            bindClose();
            return;
        }

        var stage = DATA.stages[q.stage - 1];
        if (!stage) return;

        html += '<div class="rq-title">Этап ' + stage.num + ' — ' + stage.name + '</div>';
        html += '<div class="rq-desc">' + stage.desc + '</div>';

        var stagePenalty = (q.stage === 2) ? 2 : (q.stage === 3) ? 3 : 0;
        if (stagePenalty > 0) {
            html += '<div class="rq-warn">⚠ Без 🔍 Частного детектива этот этап даст +' +
                    stagePenalty + ' подозрения.</div>';
        }

        html += '<div class="rq-suspicion">Подозрение ИСБ: <b>' +
                (q.suspicion || 0) + ' / ' + SUSPICION_THRESHOLD + '</b></div>';

        var agents = [];
        try { agents = JSON.parse(localStorage.getItem('galaxy_agents') || '[]'); } catch(e) {}
        var activeQuest = agents.find(function(a) { return a.mission_type === 'rayt_quest'; });

        if (activeQuest) {
            var left = activeQuest.returnDay - getCurrentDay();
            html += '<div class="rq-agent-info">🕵 Агент работает. Вернётся на день ' +
                    activeQuest.returnDay + '. Осталось: ' + left + ' дн.</div>';
            html += '<div class="rq-actions"><button class="rq-btn rq-btn-close" id="rqCloseBtn">Закрыть</button></div>';
        } else {
            var free = agents.filter(function(a) { return a.status === 'free'; });
            if (free.length > 0) {
                var det = free.find(isDetective);
                var whoText = det
                    ? 'разведчик №' + det.slot + ' 🔍 Частный детектив '
                    : 'разведчик №' + free[0].slot + ' ';
                html += '<div class="rq-agent-info">Будет отправлен: ' + whoText + '</div>';
                html += '<div class="rq-actions">' +
                        '<button class="rq-btn" id="rqSendBtn">🕵 Отправить агента</button>' +
                        '<button class="rq-btn rq-btn-close" id="rqCloseBtn">Закрыть</button>' +
                        '</div>';
            } else {
                html += '<div class="rq-warn">⚠ Все разведчики заняты.</div>';
                html += '<div class="rq-actions"><button class="rq-btn rq-btn-close" id="rqCloseBtn">Закрыть</button></div>';
            }
        }

        body.innerHTML = html;
        var sendBtn = document.getElementById('rqSendBtn');
        if (sendBtn) sendBtn.addEventListener('click', sendAgentOnQuest);
        bindClose();
    }

    function bindClose() {
        var c = document.getElementById('rqCloseBtn');
        if (c) c.addEventListener('click', closeRaytQuest);
    }

    function sendAgentOnQuest() {
        var q = loadQuest() || defaultQuest();
        if (q.completed || q.failed) return;

        var agents = [];
        try { agents = JSON.parse(localStorage.getItem('galaxy_agents') || '[]'); } catch(e) {}

        var slot = agents.find(function(a) { return a.status === 'free' && a.skill === 'detective'; });
        if (!slot) slot = agents.find(function(a) { return a.status === 'free'; });
        if (!slot) { alert('Нет свободных агентов.'); return; }

        var day = getCurrentDay();
        slot.status = 'working';
        slot.mission_type = 'rayt_quest';
        slot.target = 'Аэродия';
        slot.level = 'quest';
        slot.quest_stage = q.stage;
        slot.sentDay = day;
        slot.returnDay = day + 2;

        try { localStorage.setItem('galaxy_agents', JSON.stringify(agents)); } catch(e) {}

        if (typeof window.renderAgentsPanel === 'function') window.renderAgentsPanel();
        renderQuest();
    }

    document.addEventListener('click', function(e) {
        if (e.target && e.target.id === 'raytQuestStartBtn') openRaytQuest();
    });
    document.addEventListener('click', function(e) {
        if (e.target && e.target.id === 'raytQuestClose') closeRaytQuest();
        if (e.target && e.target.id === 'raytQuestOverlay') closeRaytQuest();
    });
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') closeRaytQuest();
    });

    window.openRaytQuest = openRaytQuest;
    window.closeRaytQuest = closeRaytQuest;
})();
</script>
"""
