# ЗАЩИТА ОТ U+2028 
# ============================================================
_diag = {
    '\u2028': 'U+2028 (LINE SEPARATOR)',
    '\u2029': 'U+2029 (PARAGRAPH SEPARATOR)',
}
for _ch, _name in _diag.items():
    _cnt = html.count(_ch)
    if _cnt:
        _idx = html.index(_ch)
        print(f"⚠ НАЙДЕН {_name}: {_cnt} раз(а). Первое вхождение на позиции {_idx}:")
        print(f"   контекст: ...{html[max(0,_idx-80):_idx+80]!r}...")
    else:
        print(f"✓ {_name}: не найден")

# Escaping — превращаем raw-символы в \u2028 / \u2029 внутри JS-строк
html = html.replace('\u2028', '\\u2028').replace('\u2029', '\\u2029')

with open("galaxy_map_interactive.html", "w", encoding="utf-8") as f:
    f.write(html)

print("OK")
